# owner: platform
"""Short absence notices for parents."""

from typing import Iterable

from rosterkit.models import Mark, Student
from rosterkit.attendance import days_missed


def _check_owner(student, marks):
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(
                f"mark for {mark.student_id!r} is not "
                f"for {student.student_id!r}"
            )


def _nonempty(days):
    if not days:
        raise ValueError("no absences to report")
    return days


def _count_text(days):
    count = len(days)
    return f"{count} day" + ("" if count == 1 else "s")


def _compose(student, days):
    name = f"{student.first_name} {student.last_name}"
    dates = ", ".join(day.isoformat() for day in days)
    return (
        f"{name} was absent for {_count_text(days)}. "
        f"Dates: {dates}."
    )


# ---
def absence_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    marks = list(marks)
    _check_owner(student, marks)
    days = _nonempty(days_missed(marks))
    return _compose(student, days)
